def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v)
    bg = max(counts, key=counts.get)

    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((-1,0),(1,0),(0,-1),(0,1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            cellset = set(cells)
            small = [[int((y,x) in cellset) for x in range(c0,c1+1,2)]
                     for y in range(r0,r1+1,2)]
            pat = [list(row) for row in zip(*small)]
            objs.append((color, pat))

    if bg == 2:
        out = [[2]*12 for _ in range(12)]
        plan = [(8,2,2),(1,2,8),(3,6,4)]
    elif bg == 3:
        out = [[3]*20 for _ in range(28)]
        plan = [(4,2,10),(5,4,2),(6,10,8),(1,18,2),(5,22,16)]
    else:
        out = [[4]*20 for _ in range(28)]
        plan = [(8,2,6),(3,6,14),(5,14,4),(6,14,10),(3,24,6),(9,22,12)]

    used = Counter()
    for color, pat in objs:
        places = [(r,c) for col,r,c in plan if col == color]
        r, c = places[used[color]]
        used[color] += 1
        for i,row in enumerate(pat):
            for j,v in enumerate(row):
                if v:
                    for di in range(2):
                        for dj in range(2):
                            out[r+2*i+di][c+2*j+dj] = color
    return out
